-- ############# PRODUCTOS ############## --
CREATE TABLE PAIS (
    id_pais INT PRIMARY KEY,
    nombre_pais VARCHAR(100) UNIQUE
);
CREATE TABLE REGION (
    id_region INT PRIMARY KEY,
    nombre_region VARCHAR(100) UNIQUE
);
CREATE TABLE TIPO_CLUB (
    id_tipo_club INT PRIMARY KEY,
    tipo_club VARCHAR(30) UNIQUE
);
CREATE TABLE EQUIPO (
    id_equipo INT PRIMARY KEY,
    nombre_equipo VARCHAR(100) UNIQUE,
    id_pais INTEGER REFERENCES PAIS(id_pais),
    id_tipo_club INTEGER REFERENCES TIPO_CLUB(id_tipo_club)
);
CREATE TABLE TEMPORADA (
    id_temporada INT PRIMARY KEY,
    descripcion_temporada VARCHAR(20) UNIQUE,
    año_inicio INT,
    año_fin INT
);
CREATE TABLE CATEGORIA (
    id_categoria INT PRIMARY KEY,
    nombre_categoria VARCHAR(30) UNIQUE
);
CREATE TABLE MARCA (
    id_marca INT PRIMARY KEY,
    nombre_marca VARCHAR(100) UNIQUE
);
CREATE TABLE GENERO (
    id_genero INT PRIMARY KEY,
    descripcion_genero VARCHAR(20) UNIQUE
);
CREATE TABLE TALLA (
    id_talla INT PRIMARY KEY,
    descripcion_talla VARCHAR(5) UNIQUE
);
CREATE TABLE TIPO_CAMISETA (
    id_tipo_camiseta INT PRIMARY KEY,
    descripcion_tipo VARCHAR(30) UNIQUE
);
CREATE TABLE CAMISETA (
    id_camiseta INT PRIMARY KEY,
    id_equipo INTEGER REFERENCES EQUIPO(id_equipo),
    id_temporada INTEGER REFERENCES TEMPORADA(id_temporada),
    id_categoria INTEGER REFERENCES CATEGORIA(id_categoria),
    id_marca INTEGER REFERENCES MARCA(id_marca),
    id_tipo_camiseta INTEGER REFERENCES TIPO_CAMISETA(id_tipo_camiseta),
    descripcion_camiseta VARCHAR(200),
    imagen_url VARCHAR(1000)
);
CREATE TABLE PRODUCTO (
    id_producto INT PRIMARY KEY,
    id_camiseta INTEGER REFERENCES CAMISETA(id_camiseta),
    id_genero INTEGER REFERENCES GENERO(id_genero),
    id_talla INTEGER REFERENCES TALLA(id_talla),
    precio NUMERIC(10,2),
    stock INT,
    sku VARCHAR(200) UNIQUE,
    activo BOOLEAN DEFAULT TRUE -- nuevo
);

CREATE TABLE EQUIPO_REGION (
    id_equipo INTEGER REFERENCES EQUIPO(id_equipo),
    id_region INTEGER REFERENCES REGION(id_region),
    PRIMARY KEY (id_equipo, id_region)
);

-- ############# USUARIOS ############## --
CREATE TABLE ROL (
    id_rol INT PRIMARY KEY,
    nombre_rol VARCHAR(20) UNIQUE
);

CREATE TABLE USUARIO (
    id_usuario SERIAL PRIMARY KEY,
    nombre VARCHAR(50),
    apellido VARCHAR(50),
    correo VARCHAR(100) UNIQUE,
    password VARCHAR(200),
    activo BOOLEAN DEFAULT TRUE,
    id_rol INT REFERENCES ROL(id_rol),
    fecha_registro TIMESTAMP DEFAULT CURRENT_TIMESTAMP -- nuevo
);

CREATE TABLE DIRECCION (
    id_direccion SERIAL PRIMARY KEY,
    id_usuario INT REFERENCES USUARIO(id_usuario),
    direccion VARCHAR(200),
    ciudad VARCHAR(100),
    region VARCHAR(100),
    codigo_postal VARCHAR(20),
    pais VARCHAR(100),
    telefono VARCHAR(20)
);

CREATE TABLE CARRITO (
    id_carrito SERIAL PRIMARY KEY,
    id_usuario INT REFERENCES USUARIO(id_usuario)
);

CREATE TABLE CARRITO_ITEM (
    id_carrito INT REFERENCES CARRITO(id_carrito),
    id_producto INT REFERENCES PRODUCTO(id_producto),
    cantidad INT,
    guardado BOOLEAN DEFAULT FALSE, -- TRUE si es "Guardado para después"
    PRIMARY KEY (id_carrito, id_producto, guardado)
);

CREATE TABLE METODO_PAGO (
    id_metodo_pago INT PRIMARY KEY,
    nombre_metodo VARCHAR(30) UNIQUE
);

-- ############# NUEVAS TABLAS PARA FUNCIONALIDAD ECOMMERCE ############## --
CREATE TABLE METODO_ENVIO ( -- nuevo
    id_metodo_envio INT PRIMARY KEY,
    nombre_envio VARCHAR(50) UNIQUE,
    costo NUMERIC(10,2),
    descripcion VARCHAR(200)
);

CREATE TABLE ESTADO_ORDEN ( -- nuevo
    id_estado_orden INT PRIMARY KEY,
    nombre_estado VARCHAR(30) UNIQUE
);

CREATE TABLE ORDEN ( -- nuevo
    id_orden SERIAL PRIMARY KEY,
    id_usuario INT REFERENCES USUARIO(id_usuario),
    id_direccion INT REFERENCES DIRECCION(id_direccion),
    id_metodo_pago INT REFERENCES METODO_PAGO(id_metodo_pago),
    id_metodo_envio INT REFERENCES METODO_ENVIO(id_metodo_envio),
    id_estado_orden INT REFERENCES ESTADO_ORDEN(id_estado_orden),
    total NUMERIC(10,2),
    fecha TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE DETALLE_ORDEN ( -- nuevo
    id_detalle SERIAL PRIMARY KEY,
    id_orden INT REFERENCES ORDEN(id_orden),
    id_producto INT REFERENCES PRODUCTO(id_producto),
    cantidad INT,
    precio_unitario NUMERIC(10,2),
    subtotal NUMERIC(10,2)
);

CREATE TABLE SERIE ( -- nuevo
    id_serie SERIAL PRIMARY KEY,
    nombre_serie VARCHAR(100) UNIQUE,
    descripcion VARCHAR(200),
    imagen_url VARCHAR(1000)
);

CREATE TABLE SERIE_PRODUCTO ( -- nuevo
    id_serie INT REFERENCES SERIE(id_serie),
    id_producto INT REFERENCES PRODUCTO(id_producto),
    PRIMARY KEY (id_serie, id_producto)
);

-- ############# OPCIONAL: LOGS/VENTAS/DASHBOARD ############## --
CREATE TABLE LOG_ACTIVIDAD ( -- nuevo (opcional)
    id_log SERIAL PRIMARY KEY,
    id_usuario INT REFERENCES USUARIO(id_usuario),
    tipo_actividad VARCHAR(100),
    descripcion VARCHAR(200),
    fecha TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

